        elif _is_seq(dist):
            customers = list(range(len(dist)))
            customers = [c for c in customers if c != depot]
        else:
            customers = []

    customers = list(customers)
    customers = [c for c in customers if c != depot]

    def demand(c):
        if isinstance(demands, dict):
            return demands.get(c, 1)
        if _is_seq(demands) and isinstance(c, int) and 0 <= c < len(demands):
            return demands[c]
        return 1

    if capacity is None:
        capacity = sum(demand(c) for c in customers)
        if capacity <= 0:
            capacity = 1

    def dist_ij(i, j):
        if _is_seq(dist):
            try:
                return dist[i][j]
            except Exception:
                pass
        if _is_seq(coords):
            try:
                xi, yi = coords[i]
                xj, yj = coords[j]
                dx = xi - xj
                dy = yi - yj
                return (dx * dx + dy * dy) ** 0.5
            except Exception:
                pass
        return abs(i - j)

    def route_cost(r):
        if not r:
            return 0
        c = dist_ij(depot, r[0]) + dist_ij(r[-1], depot)
        for i in range(len(r) - 1):
            c += dist_ij(r[i], r[i + 1])
        return c

    def route_demand(r):
        s = 0
        for c in r:
            s += demand(c)
        return s

    # Initial deterministic greedy insertion by nearest customer
    unassigned = customers[:]
    unassigned.sort(key=lambda c: (dist_ij(depot, c), c))
    routes = []
    while unassigned:
        r = []
        load = 0
        cur = depot
        i = 0
        while i < len(unassigned):
            c = unassigned[i]
            dc = demand(c)
            if load + dc <= capacity:
                r.append(c)
                load += dc
                cur = c
                unassigned.pop(i)
            else:
                i += 1
        if not r:
            r = [unassigned.pop(0)]
        routes.append(r)

    # Merge routes using savings
    def endpoint_info(r):
        return r[0], r[-1]

    changed = True
    while changed:
        changed = False
        best = None
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                ri = routes[i]
                rj = routes[j]
                if route_demand(ri) + route_demand(rj) > capacity:
                    continue
                ai, bi = endpoint_info(ri)
                aj, bj = endpoint_info(rj)
                cand = [
                    (dist_ij(depot, ai) + dist_ij(depot, aj) - dist_ij(ai, aj), ri + rj, i, j),
                    (dist_ij(depot, ai) + dist_ij(depot, bj) - dist_ij(ai, bj), ri + rj[::-1], i, j),
                    (dist_ij(depot, bi) + dist_ij(depot, aj) - dist_ij(bi, aj), ri[::-1] + rj, i, j),
                    (dist_ij(depot, bi) + dist_ij(depot, bj) - dist_ij(bi, bj), ri[::-1] + rj[::-1], i, j),
                ]
                cand.sort(key=lambda x: (-x[0], x[1][0], len(x[1])))
                if best is None or cand[0][0] > best[0] or (cand[0][0] == best[0] and cand[0][1] < best[1]):
                    best = cand[0]
        if best and best[0] > 0:
            _, merged, i, j = best
            routes[i] = merged
            routes.pop(j)
            changed = True

    # Simple improvement: intra-route 2-opt
    def two_opt(r):
        if len(r) < 4:
            return r
        best_r = r
        best_cost = route_cost(r)
        n = len(r)
        for i in range(n - 1):
            for j in range(i + 2, n):
                if i == 0 and j == n - 1:
                    continue
                nr = r[:i + 1] + r[i + 1:j + 1][::-1] + r[j + 1:]
                nc = route_cost(nr)
                if nc + 1e-12 < best_cost:
                    best_cost = nc
                    best_r = nr
        return best_r

    improved = True
    while improved:
        improved = False
        for idx in range(len(routes)):
            nr = two_opt(routes[idx])
            if nr != routes[idx]:
                routes[idx] = nr
                improved = True
                break

    # Final cleanup: ensure all customers appear exactly once, add missing as singleton routes
    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1
    missing = [c for c in customers if seen.get(c, 0) == 0]
    for c in missing:
        routes.append([c])

    # Remove accidental duplicates by keeping first occurrence, later duplicates become missing and are dropped
    seen_once = set()
    cleaned = []
    for r in routes:
        nr = []
        for c in r:
            if c not in seen_once:
                nr.append(c)
                seen_once.add(c)
        if nr:
            cleaned.append(nr)
    routes = cleaned

    # Re-add any still-missing customers
    present = set()
    for r in routes:
        for c in r:
            present.add(c)
    for c in customers:
        if c not in present:
            routes.append([c])

    return routes
